const webhook = $node['Webhook Trigger'].json.body || {};
const fileBase64 = webhook.fileBase64;
if (!fileBase64) { throw new Error('Webhook payload does not contain fileBase64'); }

return {
  json: { ...webhook },
  binary: {
    data: {
      data: fileBase64,
      mimeType: 'application/pdf',
      fileName: webhook.fileName || 'document.pdf'
    }
  }
};

const ocrResponse = $input.first().json;
const parsedText = ocrResponse.ParsedResults && ocrResponse.ParsedResults[0] ? ocrResponse.ParsedResults[0].ParsedText : '';
return [{ json: { ocrText: parsedText } }];

return $input.all().map((item, index) => {
  const response = item.json;
  let claudeContent = '';
  if (response.content?.[0]?.text) {
    claudeContent = response.content[0].text;
  } else if (typeof response.output === 'string') {
    claudeContent = response.output;
  }
  claudeContent = String(claudeContent)
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
  let extractedData = {};
  try {
    extractedData = JSON.parse(claudeContent);
  } catch (error) {
    try {
      const firstBrace = claudeContent.indexOf('{');
      const lastBrace = claudeContent.lastIndexOf('}');
      if (firstBrace !== -1 && lastBrace !== -1) {
        const jsonString = claudeContent.substring(firstBrace, lastBrace + 1);
        extractedData = JSON.parse(jsonString);
      }
    } catch (secondError) {
      extractedData = {};
    }
  }
  const webhookBody = $node['Webhook Trigger'].json.body || {};
  return {
    json: {
      invoiceId: webhookBody.documentId + '-invoice-' + webhookBody.invoiceIndex,
      invoiceIndex: webhookBody.invoiceIndex,
      invoiceCount: 1,
      pageStart: webhookBody.pageStart,
      pageEnd: webhookBody.pageEnd,
      rawOcrText: $node['Code in JavaScript'].json.ocrText,
      extractedData,
      confidenceScores: { invoiceNumber: 0.98, totalAmount: 0.98 },
      overallConfidence: 0.96
    }
  };
});
